import 'package:cephalopod/core/board/models/board_ui.dart';
import 'package:cephalopod/core/saved_game/saved_game_summary.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'saved_game_ui.freezed.dart';

/// The saved game as Home's Continue card shows it: its [board], each side
/// (who it is, its dice, whether it is to move), and the computer's level,
/// or `null` against a friend.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class SavedGameUi with _$SavedGameUi {
  const factory SavedGameUi({
    required BoardUi board,
    required SideSummary black,
    required SideSummary white,
    ComputerLevel? computerLevel,
  }) = _SavedGameUi;
}
